package com.bank.summaryconv;

import java.util.*;
import java.util.logging.*;

public class ToCountsDemo {
    private static final Logger log = Logger.getLogger("SummaryConv");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Map<String, List<Employee>> byDept = Map.of(
            "IT", List.of(new Employee("Rajesh"), new Employee("Amit")),
            "Sales", List.of(new Employee("Priya")));
        SummaryConverterService service = new SummaryConverterService();

        Map<String, Long> counts = service.toCounts(byDept);
        log.info(() -> "Counts per department: " + counts);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    Employee(String name) { this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/SummaryConverterService.java ───
class SummaryConverterService {
    Map<String, Long> toCounts(Map<String, List<Employee>> byDept) {
        return byDept.entrySet().stream()
            .collect(java.util.stream.Collectors.toMap(
                Map.Entry::getKey,                       // keep department
                e -> (long) e.getValue().size()));       // list → count (as Long)
    }
}
